export function lookupBrandIcon(id: string, logoDomain?: string): BrandIcon | null {
  const key = (id || '').toLowerCase().replace(/^cust_/, '')
  if (SERVICE_ICONS[key]) return SERVICE_ICONS[key]
  const base = (logoDomain || '').toLowerCase().split('.')[0]
  if (base && SERVICE_ICONS[base]) return SERVICE_ICONS[base]
  return null
}
